  "loc.src.data.namedaces.field.name.5b98a3f56f79": "Voss of Shaft Seven",
  "loc.src.data.namedaces.field.name.664f9b6d2afa": "Mako of the Broken Ring",
  "loc.src.data.namedaces.field.name.71c2aca29db1": "Serrat of the Ninth Clause",
