  "loc.src.systems.input.template.text.3ce41488e5d0": "0)) { this.destroy(); } this._initialized = true; this._inputContext = ctx; this.state = ctx.state; this.bus = ctx.bus; this.helpers = ctx.helpers; this._domBindings = []; const keys = (this._keys = Object.create(null)); this._ndc = { x: 0, y: 0 }; const viewportW = typeof innerWidth === 'number' ? innerWidth : 0; const viewportH = typeof innerHeight === 'number' ? innerHeight : 0; this._screen = { x: Math.floor(viewportW * 0.5), y: Math.floor(viewportH * 0.5), active: false }; resetAutoTargetPath(this, this.state); this._m0 = false; this._m1 = false; this._m2 = false; this._cmHeld = false; this._gamepadLifecycleQuarantine = { massline: true, countermeasure: true, travelBurn: true, autoTarget: true, chargeDetonate: true, deployRepulsor: true, }; this._masslineGrammar = createMasslineInputGrammar(); // F4/G9: device arbitration uses deterministic (tick, sequence) activity stamps shared // across keyboard/gamepad/touch — never performance.now()/Date.now(). Sequence reflects // actual event order within a tick (not device-type priority). this._lastKbmTick = -1; this._lastKbmSeq = -1; this._kbmActivityPending = false; this._inputActivitySeq = 0; this._lastInputWallMs = 0; this._canvas = (typeof document !== 'undefined') ? document.getElementById('gl-canvas') : null; this.gamepad = createGamepad(ctx); ctx.gamepad = this.gamepad; // Touch layer (P1-12): virtual dual-stick + buttons for touchscreens. Auto-detects on touch // devices; the overlay is built lazily. Merged below alongside gamepad so gameplay is unchanged. this.touch = createTouch(ctx); ctx.touch = this.touch; this.touch.autoDetect(); // H3: DOM adapter is browser-only. Deterministic grammar/key state initializes without window. // Node hosts (lab production-manifest path) keep pure reducer state; tape driver writes keys. if (typeof window === 'undefined' || !window || typeof window.addEventListener !== 'function') { this._domAdapterAttached = false; return; } this._domAdapterAttached = true; this._attachDomInputAdapter(keys); }, /** * Browser-only: wire keyboard/pointer/gamepad listeners. Must not run under Node. * @param {Record",
