  "loc.src.systems.missions.field.brief.021371109268": "The drop was a sting. {homeName} will still take the book if you make it back.",
  "loc.src.systems.missions.field.brief.8b2e57471b2c": "A witness marked the hull. {info_name} pays for the {goodsName} that is still out there.",
  "loc.src.systems.missions.field.brief.af2203028838": "{massU}u on the tether to {dest_name}. Paid on mass landed, not mass hooked.",
  "loc.src.systems.missions.field.brief.c488e8820ba2": "The distress was an ambush. {homeName} wants the field empty.",
  "loc.src.systems.missions.field.label.1f25a845cb7a": "HAUL",
