  "loc.src.systems.missions.field.text.008baf915cbe": "{receipt_houseText}{recoverySuffix}",
  "loc.src.systems.missions.field.text.00f68fcdc9d8": "Escort: wait for the convoy to dock",
  "loc.src.systems.missions.field.text.04762d467e0f": "CONTRACT 47-A: PAYMENT WITHHELD. STATUS: PENDING. MASS RECONCILED TO LOG.",
  "loc.src.systems.missions.field.text.1110f6a4b38b": "Follow-up contract available",
  "loc.src.systems.missions.field.text.166762e1bab2": "47-A sample missing. Recovery site re-marked.",
  "loc.src.systems.missions.field.text.1dcad4cacfae": "You're into the wreck — bring what's left of it home to {home}. The desk pays for what comes back.",
  "loc.src.systems.missions.field.text.205bcd8c8d3f": "Too many active missions",
  "loc.src.systems.missions.field.text.34952e5c80cb": "Free {need_have_loaded}u cargo for Kessler's replacement",
  "loc.src.systems.missions.field.text.5692925ef49a": "Cargo hold cannot receive the sealed manifest",
  "loc.src.systems.missions.field.text.73fb49a03b70": "PAYMENT WITHHELD — CONTRACT 47-A STATUS: PENDING / OPEN",
  "loc.src.systems.missions.field.text.81e7f28b0024": "Delivery: you are not carrying {need}",
  "loc.src.systems.missions.field.text.843199a6f079": "That wreck already has a different disposition",
  "loc.src.systems.missions.field.text.85897ba83014": "Mission FAILED: {m_title}",
  "loc.src.systems.missions.field.text.924eb7ebedc3": "Partial recovery: {deal_deliverQty}/{need}u brought home — settled for {deal_payCr_toLocaleString_en_US} cr.",
  "loc.src.systems.missions.field.text.95b7a55eaec2": "Contract void: the mark for {m_title} was destroyed — deposit refunded.",
  "loc.src.systems.missions.field.text.a2541e3717b6": "Sealed cargo missing. Return to Helios.",
  "loc.src.systems.missions.field.text.c491fa79ff32": "Mission expired: {m_title}",
  "loc.src.systems.missions.field.text.df2a8113f623": "Proving Ground: {story_chainProgress}/{wantCount}",
  "loc.src.systems.missions.field.text.ebb7ce6463ca": "Short manifest logged. It isn't the whole convoy, but it settles what came home to {home}.",
  "loc.src.systems.missions.field.text.f3afae19cb66": "The wreck's gone cold and the file is closed at {home}. No payment, no blame — there was nothing left to bring home.",
  "loc.src.systems.missions.field.text.fd986a11e0ad": "Full {qty}u manifest home at {home}. The convoy's file is closed with thanks — settled in full.",
  "loc.src.systems.missions.field.title.4d5bed8bdc73": "Recover {qty}u {goodsName} for {info_name}",
  "loc.src.systems.missions.field.title.bad47cabee72": "Tether-haul {massU}u {commodity_commodity_name_Ore} to {dest_name}",
  "loc.src.systems.missions.field.title.ef6ef10373ff": "The pods were bait — clear the field for {homeName}",
