  "loc.src.systems.onboarding.field.label.c8ee0808465f": "Scout",
  "loc.src.systems.onboarding.field.label.f0955f861561": "Scrap",
  "loc.src.systems.onboarding.field.label.fe9d3bccbf23": "Loose Rock",
  "loc.src.systems.onboarding.field.line.0c10ddd9ccc3": "Thrust away until the trainer leaves scope.",
  "loc.src.systems.onboarding.field.line.1ef83540c544": "Claimed salvage. Take it anyway, or leave it.",
  "loc.src.systems.onboarding.field.line.270b836ea4c3": "Pulse the scanner.",
  "loc.src.systems.onboarding.field.line.2f39817eee24": "Release. Let the heat bar clear.",
  "loc.src.systems.onboarding.field.line.43b60787d077": "Thrust until speed passes forty.",
  "loc.src.systems.onboarding.field.line.43d41a9faeea": "Hold course. Let the trainer cross your bow.",
  "loc.src.systems.onboarding.field.line.5202afed18bb": "Pick the work that fits.",
  "loc.src.systems.onboarding.field.line.557e63caed23": "Build speed. Let go at the big rock.",
  "loc.src.systems.onboarding.field.line.609cb17e1238": "Winch in. Hold tether to reel.",
  "loc.src.systems.onboarding.field.line.71fc12844262": "Brake below ten.",
  "loc.src.systems.onboarding.field.line.7dadd337a52d": "Fire a short burst into the trainer.",
  "loc.src.systems.onboarding.field.line.83efb637da5c": "Latch the raider. Swing him into the rock.",
  "loc.src.systems.onboarding.field.line.98f129723b2e": "Board's got one job for you.",
  "loc.src.systems.onboarding.field.line.99c2a2d0e64b": "Helios. Dock when close.",
  "loc.src.systems.onboarding.field.line.a17bd8c9825b": "Follow the amber diamond to the trainer.",
  "loc.src.systems.onboarding.field.line.b65b5e3f6379": "Target the marked derelict.",
  "loc.src.systems.onboarding.field.line.c175bac015f6": "Latch it. Massline.",
  "loc.src.systems.onboarding.field.line.cfb3b8ceaf3e": "Ease off. Let the line settle.",
  "loc.src.systems.onboarding.field.line.e0338a77cb65": "Beam the bright seams.",
  "loc.src.systems.onboarding.field.line.fd46169b2ac9": "You're marked. Outrun the search ring.",
  "loc.src.systems.onboarding.field.line.fdb70988fa59": "Cut and coast. Tap tether to cut.",
  "loc.src.systems.onboarding.field.name.b4344542139a": "onboarding",
  "loc.src.systems.onboarding.field.name.ce882614e8f3": "Nervous Hauler",
  "loc.src.systems.onboarding.field.text.0628b4ee3d15": "Welcome back. {lines_join}",
