  "loc.src.ui.nemesiscomms.attr.aria.label.0de07c079b95": "Counterexample transmission",
  "loc.src.ui.nemesiscomms.dom.textcontent.071db8874e2f": "A familiar transmission. A revised ship.",
  "loc.src.ui.nemesiscomms.dom.textcontent.1f75bb59d3af": "Opening: {kit_opening}",
  "loc.src.ui.nemesiscomms.dom.textcontent.28adfc261649": "Read the fit before you commit.",
  "loc.src.ui.nemesiscomms.dom.textcontent.4ebba029a8eb": "The guns are cooling. I have no argument left. Your choice.",
  "loc.src.ui.nemesiscomms.dom.textcontent.5a42539764d4": "No mid-fight refit.",
  "loc.src.ui.nemesiscomms.dom.textcontent.63e5bb80efe1": "The fit is committed. The pilot can still change their mind.",
  "loc.src.ui.nemesiscomms.dom.textcontent.7f7f0ad27083": "SILE ORRA / CEASE FIRE",
  "loc.src.ui.nemesiscomms.dom.textcontent.b458e30949f7": "Acceptance is permanent. Orra can still be destroyed before you accept.",
  "loc.src.ui.nemesiscomms.dom.textcontent.c75673e18901": "SILE ORRA / INBOUND",
  "loc.src.ui.nemesiscomms.dom.textcontent.e58f67acd9f5": "Act {p_act_1}: maneuver change, not new hardware.",
  "loc.src.ui.nemesiscomms.dom.textcontent.ebcf74e87fe9": "SILE ORRA / {NEMESIS_CHAPTERS_a_plan_chapter_title_toUpperCase}",
